() => {
  const sections = document.querySelectorAll('section');
  const hero = sections[0]; // the first section is the hero

  const testimonials = [
    {
      quote: "BaroCSS made our design-to-code loop instant. We ship UI changes without ever waiting on a build.",
      name: "Amara Okafor",
      role: "Frontend Engineer, Lumen",
    },
    {
      quote: "The runtime output stays tiny even as our component library grows. It's exactly what we needed.",
      name: "Daniel Reyes",
      role: "Product Designer, Northwind",
    },
    {
      quote: "Zero build config and a great developer experience. It works identically in our SSR and client apps.",
      name: "Mei Tanaka",
      role: "Full-stack Dev, Kite",
    },
  ];

  const cards = testimonials.map(t => `
          <figure class="flex flex-col rounded-2xl border border-slate-200 bg-white p-6 shadow-sm hover:shadow-lg hover:-translate-y-0.5 transition">
            <blockquote class="text-slate-700 leading-relaxed">“${t.quote}”</blockquote>
            <figcaption class="mt-6 flex items-center gap-3">
              <span class="inline-flex h-11 w-11 shrink-0 items-center justify-center rounded-full bg-gradient-to-br from-blue-500 to-indigo-500 text-white font-semibold">${t.name.split(' ').map(w => w[0]).join('').slice(0,2)}</span>
              <span class="flex flex-col">
                <span class="text-sm font-semibold text-slate-900">${t.name}</span>
                <span class="text-xs text-slate-500">${t.role}</span>
              </span>
            </figcaption>
          </figure>`).join('');

  const section = document.createElement('section');
  section.id = 'testimonials';
  section.className = 'py-16 sm:py-20 border-t border-slate-200';
  section.innerHTML = `
      <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div class="mx-auto max-w-3xl text-center">
          <span class="inline-flex items-center gap-2 rounded-full border border-slate-200 bg-white px-3 py-1 text-xs font-medium text-slate-600">Testimonials</span>
          <h2 class="mt-3 text-3xl sm:text-4xl font-bold tracking-tight text-slate-900">Loved by developers</h2>
          <p class="mt-3 text-slate-600">Teams building with BaroCSS on what changed for them.</p>
        </div>
        <div class="mt-10 grid grid-cols-1 lg:grid-cols-3 gap-6">${cards}</div>
      </div>`;

  hero.insertAdjacentElement('afterend', section);
  return 'inserted after: ' + hero.outerHTML.slice(0, 40);
}

