() => {
  const grid = document.querySelector('#testimonials .grid');
  const avatar = document.querySelector('#testimonials figcaption span');
  const results = {};
  const gcs = getComputedStyle(grid);
  results.wideCols = gcs.gridTemplateColumns;
  const acs = getComputedStyle(avatar);
  results.avatar = { w: acs.width, h: acs.height, radius: acs.borderRadius };
  results.cardCount = document.querySelectorAll('#testimonials figure').length;
  return results;
}

